public class TestConfigTemplate {

	@Test
	public final void testNonEscapeOfAlternateMultilineDelimiter() {
		String value = "I contain a '''multiline\nstring''' that shouldn't be escaped.";
		assertEquals(ConfigTemplate.escapeMultilineQuotes("\"\"\"", value), value);
		value = "I contain a \"\"\"multiline\nstring\"\"\" that shouldn't be escaped.";
		assertEquals(ConfigTemplate.escapeMultilineQuotes("'''", value), value);
	}

	@Test
	public final void testEscapeOfSpecifiedMultilineDelimiter() {
		String value = "I contain a '''multiline\nstring''' that should be escaped.";
		assertEquals(ConfigTemplate.escapeMultilineQuotes("'''", value),
				"I contain a \\'\\'\\'multiline\nstring\\'\\'\\' that should be escaped.");
		value = "I contain a \"\"\"multiline\nstring\"\"\" that should be escaped.";
		assertEquals(ConfigTemplate.escapeMultilineQuotes("\"\"\"", value),
				"I contain a \\\"\\\"\\\"multiline\nstring\\\"\\\"\\\" that should be escaped.");
	}

	@Test
	public final void testNonEscapeOfShorterSequences() {
		String value = "' '' ''' ''''";
		assertEquals(ConfigTemplate.escapeMultilineQuotes("'''", value), "' '' \\'\\'\\' \\'\\'\\''");
		value = "\" \"\" \"\"\" \"\"\"\"";
		assertEquals(ConfigTemplate.escapeMultilineQuotes("\"\"\"", value), "\" \"\" \\\"\\\"\\\" \\\"\\\"\\\"\"");
	}

	@Test
	public final void testInvalidDelimiterThrowsException() {
		assertThrows(IllegalArgumentException.class, () -> ConfigTemplate.escapeMultilineQuotes("'", "any value"));
	}

	@Test
	public final void testSimpleCharacters() {
		ConfigTemplate temp = new ConfigTemplate("{%value%}");
		Map<String, String> map = new LinkedHashMap<>();
		map.put("value", "sob");
		assertEquals("sob", temp.render(map));
	}

	@Test
	public final void testSpecialCharacters() {
		ConfigTemplate temp = new ConfigTemplate("{%value%}");
		Map<String, String> map = new LinkedHashMap<>();
		map.put("value", "$0b");
		assertEquals("$0b", temp.render(map));
	}

	@Test
	public final void testBracketSuffixesShouldRemainPartOfVariableNames() {
		ConfigTemplate temp = new ConfigTemplate("{%Triple DB size[len=16]|1099511627776%}");
		Map<String, String> map = new LinkedHashMap<>();
		map.put("Triple DB size[len=16]", "20971520");

		assertTrue(temp.getVariableMap().containsKey("Triple DB size[len=16]"));
		assertFalse(temp.getVariableMap().containsKey("Triple DB size"));
		assertEquals("1099511627776", temp.getVariableMap().get("Triple DB size[len=16]").get(0));
		assertEquals("20971520", temp.render(map));
	}

	@Test
	public final void testInlineAttributeDefaultsShouldNotOverrideTokenDefaults() {
		String rawName = "Rule query[rows=8 cols=80 default=\"CONSTRUCT { ?s ?p ?o } WHERE { ?s ?p ?o FILTER(false) }\"]";
		ConfigTemplate temp = new ConfigTemplate("{%" + rawName + "|%}");

		assertTrue(temp.getVariableMap().containsKey(rawName));
		assertFalse(temp.getVariableMap().containsKey("Rule query"));
		assertTrue(temp.getVariableMap().get(rawName).isEmpty());
		assertEquals("", temp.render(Map.of()));
	}

	@Test
	public final void testTokenDefaultsMayContainCurlyBraces() {
		ConfigTemplate temp = new ConfigTemplate(
				"{%Rule query|CONSTRUCT { ?s ?p ?o } WHERE { ?s ?p ?o FILTER(false) }%}");

		assertEquals("CONSTRUCT { ?s ?p ?o } WHERE { ?s ?p ?o FILTER(false) }",
				temp.getVariableMap().get("Rule query").get(0));
		assertEquals("CONSTRUCT { ?s ?p ?o } WHERE { ?s ?p ?o FILTER(false) }", temp.render(Map.of()));
	}

	@Test
	public final void testLmdbTemplateDeclaresFrontierEstimatorDefaults() throws IOException {
		InputStream input = TestConfigTemplate.class.getResourceAsStream("lmdb.ttl");
		assertNotNull(input, "LMDB repository configuration template must be available");

		try (input) {
			ConfigTemplate template = new ConfigTemplate(new String(input.readAllBytes(), UTF_8));
			Model rendered = Rio.parse(new StringReader(template.render(Map.of())), "", RDFFormat.TURTLE);

			assertAll(
					() -> assertFrontierTemplateProperty(template, rendered, "sketchEstimatorEnabled",
							"Sketch estimator enabled", "false"),
					() -> assertFrontierTemplateProperty(template, rendered, "frontierEstimatorMode",
							"Frontier estimator mode", "AUTHORITATIVE"),
					() -> assertFrontierTemplateProperty(template, rendered, "frontierSynopsisBudgetBytes",
							"Frontier synopsis budget bytes", "536870912"),
					() -> assertFrontierTemplateProperty(template, rendered, "frontierQueryMemoryBudgetBytes",
							"Frontier query memory budget bytes", "67108864"),
					() -> assertFrontierTemplateProperty(template, rendered, "frontierDesignLanes",
							"Frontier design lanes", "2"),
					() -> assertFrontierTemplateProperty(template, rendered, "frontierAuditLanes",
							"Frontier audit lanes", "2"),
					() -> assertFrontierTemplateProperty(template, rendered, "frontierRefinementWorkUnits",
							"Frontier refinement work units", "4096"),
					() -> assertFrontierTemplateProperty(template, rendered, "frontierTargetRelativeStandardError",
							"Frontier target relative standard error", "0.25"),
					() -> assertFrontierTemplateProperty(template, rendered, "frontierDefensiveProposalEpsilon",
							"Frontier defensive proposal epsilon", "0.1"));
		}
	}

	private static void assertFrontierTemplateProperty(ConfigTemplate template, Model rendered, String propertyName,
			String variableName, String expectedDefault) {
		assertAll(propertyName,
				() -> {
					List<String> options = template.getVariableMap().get(variableName);
					assertNotNull(options, () -> "Missing LMDB template variable " + variableName);
					assertFalse(options.isEmpty(), () -> "Missing default for LMDB template variable " + variableName);
					assertEquals(expectedDefault, options.getFirst(),
							() -> "Wrong default for LMDB template variable " + variableName);
				},
				() -> {
					Set<Value> values = rendered
							.filter(null, Values.iri("http://rdf4j.org/config/sail/lmdb#", propertyName), null)
							.objects();
					assertEquals(1, values.size(), () -> "Missing or repeated LMDB template property " + propertyName);
					assertEquals(expectedDefault, values.iterator().next().stringValue(),
							() -> "Wrong rendered value for LMDB template property " + propertyName);
				});
	}

}
